-- 2026-27 high school events (TSA 2027 & 2028 guide).
-- Sources: tsaweb.org Themes & Problems (2026-27), HS eligibility chart (2027 & 2028),
-- rating-form pages from the official guide hosted by NC TSA. Generated 2026-11-05.
-- Running this updates the LIVE site immediately (no deploy needed).
BEGIN;

ALTER TABLE events ALTER COLUMN theme TYPE TEXT;
ALTER TABLE events ADD COLUMN IF NOT EXISTS rubric_pages TEXT;

-- Retired from the HS list in 2026-27. No teams reference them (verified 2026-11-05);
-- the NOT EXISTS guard keeps any event a team still uses.
DELETE FROM events e WHERE e.title IN ('Coding', 'Geospatial Technology', 'Senior Solar Sprint', 'Systems Control Technology')
  AND NOT EXISTS (SELECT 1 FROM teams t WHERE t.event_id = e.id);

-- Old rows used different ids; drop any old row for an event we re-insert below (unless a team uses it).
DELETE FROM events e WHERE e.id NOT IN ('animatronics', 'architectural-design', 'artificial-intelligence', 'audio-podcasting', 'automated-manufacturing-systems', 'biotechnology-design', 'board-game-design', 'chapter-team', 'childrens-stories', 'cad-architecture', 'cad-engineering', 'cybersecurity', 'data-science-and-analytics', 'debating-technological-issues', 'digital-video-production', 'dragster-design', 'drone-challenge-uav', 'engineering-design', 'extemporaneous-speech', 'fashion-design-and-technology', 'flight-endurance', 'forensic-science', 'future-technology-and-engineering-teacher', 'hybrid-racer-xl', 'interior-design', 'manufacturing-prototype', 'music-production', 'on-demand-video', 'photographic-technology', 'prepared-presentation', 'promotional-design', 'robotics', 'software-development', 'stem-mass-media', 'structural-design-and-engineering', 'technology-bowl', 'technology-problem-solving', 'transportation-modeling', 'video-game-design', 'virtual-reality-simulation', 'vlogging', 'webmaster')
  AND NOT EXISTS (SELECT 1 FROM teams t WHERE t.event_id = e.id);

ON CONFLICT (id) DO UPDATE SET title = EXCLUDED.title, theme = EXCLUDED.theme, full_theme_url = EXCLUDED.full_theme_url, description = EXCLUDED.description, category = EXCLUDED.category, team_size = EXCLUDED.team_size, types = EXCLUDED.types, rubric_url = EXCLUDED.rubric_url, rubric_pages = EXCLUDED.rubric_pages;

COMMIT;
