INSERT INTO events (id, title, theme, full_theme_url, description, category, team_size, types, rubric_url, rubric_pages) VALUES
  ('animatronics', 'Animatronics', 'Classic Tales as Mechanical Marvels', 'https://tsaweb.org/competitions/themes-and-problems?hspage=1', 'To address the annual design challenge, participants exhibit and demonstrate their knowledge of mechanical and control systems by creating an animatronic device with a specific purpose (i.e., communicate an idea, entertain, demonstrate a concept, etc.) that includes sound, lights, and an appropriate surrounding environment (a display).', 'STEM and the Arts', 'Team of 2–3', ARRAY['Model & display', 'Documentation', 'Interview']::text[], 'https://drive.google.com/file/d/1SwPAK48hAUQKy1NkzkMRvvktUQ4qYXoI/view', '46–48'),
  ('architectural-design', 'Architectural Design', 'Family-Themed Restaurant', 'https://tsaweb.org/docs/default-source/competitions/themes-and-problems-2026-2027/high-school/2027-architecutral-design-problem.pdf?sfvrsn=9f840cf2_1', 'In response to the annual design challenge, participants develop a set of architectural plans and related materials, and construct both a physical and computer-generated model and virtual walkthrough to accurately depict their design. Semifinalists deliver a presentation and participate in an interview.', 'Architecture and Construction Technology', 'Team of 2–4 or individual', ARRAY['Pre-conference submission', 'Plans & models', 'Presentation', 'Interview']::text[], 'https://drive.google.com/file/d/1SwPAK48hAUQKy1NkzkMRvvktUQ4qYXoI/view', '54–57'),
  ('artificial-intelligence', 'Artificial Intelligence (AI)', NULL, NULL, 'Applying leadership and 21st century skills, participants demonstrate knowledge of artificial intelligence (AI) concepts, models, and best practices by completing a test to qualify for semifinals. Semifinalist teams solve an onsite problem(s) using a generative artificial intelligence (GenAI) tool. Completed solutions are objectively measured to determine the best solution for the stated problem.', 'Computer Science', 'Team of 2', ARRAY['Test', 'Onsite challenge']::text[], 'https://drive.google.com/file/d/1SwPAK48hAUQKy1NkzkMRvvktUQ4qYXoI/view', '63–64'),
  ('audio-podcasting', 'Audio Podcasting', 'The Debate Desk', 'https://tsaweb.org/competitions/themes-and-problems?hspage=1', 'Participants use digital audio technology to create original content for a podcast piece that addresses the annual theme. The podcast must feature high level storytelling techniques, voice acting, and folly sound effects; the full entry must include documentation of the podcast development process and elements. Semifinalists participate in an interview.', 'Communications Technology', 'Team or individual', ARRAY['Pre-conference submission', 'Documentation', 'Interview']::text[], 'https://drive.google.com/file/d/1SwPAK48hAUQKy1NkzkMRvvktUQ4qYXoI/view', '71–74'),
  ('automated-manufacturing-systems', 'Automated Manufacturing Systems', NULL, NULL, 'Applying leadership and 21st century skills, participants collaborate to engineer and prototype an automated manufacturing system to solve a production problem. Teams analyze the prompt, build a sensor-based mechatronic solution, program the automation logic, document the mechanical and software design, and create instructions for judges to operate the system.', 'Computer Science', 'Team of 2–3', ARRAY['Prototype', 'Documentation', 'Demonstration']::text[], 'https://drive.google.com/file/d/1SwPAK48hAUQKy1NkzkMRvvktUQ4qYXoI/view', '81–83'),
  ('biotechnology-design', 'Biotechnology Design', 'Biosensors for Disease Detection', 'https://tsaweb.org/competitions/themes-and-problems?hspage=1', 'Participants select a contemporary biotechnology problem that addresses the annual theme and demonstrates understanding of the topic through documented research, the development of a solution, a display (including an optional model or prototype), and an effective multimedia presentation. Semifinalists deliver a presentation and participate in an interview.', 'Technology and Research', 'Team · 1 per chapter', ARRAY['Research', 'Display', 'Presentation', 'Interview']::text[], 'https://drive.google.com/file/d/1SwPAK48hAUQKy1NkzkMRvvktUQ4qYXoI/view', '88–90'),
  ('board-game-design', 'Board Game Design', NULL, NULL, 'Participants develop, build, and package a board game that focuses on a subject of their choice. Creative packaging, and the instructions, pieces, and cards associated with the pilot game will be evaluated. Semifinalists set up the game, demonstrate how the game is played, explain the game’s features, and discuss the design process.', 'STEM and the Arts', 'Team of 2–4', ARRAY['Game & packaging', 'Demonstration', 'Interview']::text[], 'https://drive.google.com/file/d/1SwPAK48hAUQKy1NkzkMRvvktUQ4qYXoI/view', '96–99'),
  ('chapter-team', 'Chapter Team', NULL, NULL, 'Participants take a parliamentary procedure test to qualify for the semifinal round of competition. Semifinalists conduct an opening ceremony, items of business, parliamentary actions, and a closing ceremony.', 'Leadership', 'Team of 6', ARRAY['Test', 'Onsite meeting']::text[], 'https://drive.google.com/file/d/1SwPAK48hAUQKy1NkzkMRvvktUQ4qYXoI/view', '110–112'),
  ('childrens-stories', 'Children''s Stories', 'Graphic Novel / Comic Book', 'https://tsaweb.org/competitions/themes-and-problems?hspage=1', 'In response to the annual theme, participants create an illustrated children’s story of artistic, instructional, and social value, and submit documentation related to the development of the physical storybook. Semifinalists read their story aloud and participate in an interview.', 'Communications Technology', 'Team or individual', ARRAY['Storybook', 'Documentation', 'Read-aloud', 'Interview']::text[], 'https://drive.google.com/file/d/1SwPAK48hAUQKy1NkzkMRvvktUQ4qYXoI/view', '119–121'),
  ('cad-architecture', 'CAD Architecture', NULL, NULL, 'Participants use complex computer graphic skills, tools, and processes to respond to a design challenge in which they develop representations of architectural subjects, such as foundation and/or floor plans, and/or elevation drawings, and/or details of architectural ornamentation or cabinetry. The solution to the design challenge and participant answers in an interview are evaluated.', 'Architecture and Construction Technology', 'Individual', ARRAY['Onsite challenge', 'Interview']::text[], 'https://drive.google.com/file/d/1SwPAK48hAUQKy1NkzkMRvvktUQ4qYXoI/view', '127–129'),
  ('cad-engineering', 'CAD Engineering', NULL, NULL, 'Participants use complex computer graphic skills, tools, and processes to respond to a design challenge in which they develop three-dimensional representations of engineering subjects, such as a machine part, tool, device, or manufactured product. The solution to the design challenge and participant answers in an interview are evaluated.', 'Architecture and Construction Technology', 'Individual', ARRAY['Onsite challenge', 'Interview']::text[], 'https://drive.google.com/file/d/1SwPAK48hAUQKy1NkzkMRvvktUQ4qYXoI/view', '135–137'),
  ('cybersecurity', 'Cybersecurity', NULL, NULL, 'Applying leadership and 21st century skills, participants respond to a cybersecurity challenge by identifying a breach in computer security via “Capture the Flag” games. Areas of challenge might include exploit development, digital puzzles, cryptography, reverse engineering, binary analysis, mobile security, etc. Participants must accurately address a series of on-site problems within a specified, limited amount of time.', 'Computer Science', 'Team of 2–4', ARRAY['Onsite challenge']::text[], 'https://drive.google.com/file/d/1SwPAK48hAUQKy1NkzkMRvvktUQ4qYXoI/view', '144'),
  ('data-science-and-analytics', 'Data Science and Analytics', 'AI-Generated Climate & Sustainability Data', 'https://tsaweb.org/competitions/themes-and-problems?hspage=1', 'Participants identify a societal issue, collect or compile data from various sources about the issue, and then produce documentation and a digital scientific poster about their findings. Semifinalists create a synopsis and digital visual representation of a data set provided in an onsite challenge.', 'Computer Science', 'Team of 2 or individual', ARRAY['Pre-conference submission', 'Poster', 'Onsite challenge']::text[], 'https://drive.google.com/file/d/1SwPAK48hAUQKy1NkzkMRvvktUQ4qYXoI/view', '151–153'),
  ('debating-technological-issues', 'Debating Technological Issues', 'AI in Medicine', 'https://tsaweb.org/competitions/themes-and-problems?hspage=1', 'Participants research the annual topic and subtopics and prepare for a debate against a team from another chapter. Teams are instructed to take either the pro or con side of a selected subtopic, submit a summary of references, and use their research to support their assigned position. The quality of a team’s debate determines semifinalists and finalists.', 'Communications Technology', 'Team of 2', ARRAY['Research', 'Onsite debate']::text[], 'https://drive.google.com/file/d/1SwPAK48hAUQKy1NkzkMRvvktUQ4qYXoI/view', '161–163'),
  ('digital-video-production', 'Digital Video Production', '1990s-Style Infomercial', 'https://tsaweb.org/competitions/themes-and-problems?hspage=1', 'Participants develop and submit a digital video and a documentation portfolio (including such items as a storyboard, script, summary of references and sources, and equipment list) that reflects the annual theme. Semifinalists participate in an interview.', 'STEM and the Arts', 'Team or individual', ARRAY['Pre-conference submission', 'Documentation', 'Interview']::text[], 'https://drive.google.com/file/d/1SwPAK48hAUQKy1NkzkMRvvktUQ4qYXoI/view', '170–172'),
  ('dragster-design', 'Dragster Design', 'Inside / Out', 'https://tsaweb.org/competitions/themes-and-problems?hspage=2', 'Participants design, draw, and construct a CO2-powered dragster that adheres to specifications, design and documentation requirements, and the annual theme. Semifinalists compete in a double-elimination race and participate in an interview.', 'Manufacturing and Transportation Technology', 'Individual', ARRAY['Model', 'Documentation', 'Race', 'Interview']::text[], 'https://drive.google.com/file/d/1SwPAK48hAUQKy1NkzkMRvvktUQ4qYXoI/view', '180–182'),
  ('drone-challenge-uav', 'Drone Challenge (UAV)', 'Humanitarian Aid and Rescue', 'https://tsaweb.org/docs/default-source/competitions/themes-and-problems-2026-2027/high-school/2027-hs-drone-challenge-theme.pdf?sfvrsn=476818b7_1', 'Participants design, build, assemble, document, and test fly an open-source Unmanned Arial Vehicle (UAV) according to the stated annual theme/problem specifications. The required documentation portfolio must include elements such as a photographic log, wiring schematics, and a description of the programming software used. Semifinalists participate in an interview.', 'Manufacturing and Transportation Technology', 'Team of 2–6', ARRAY['Build', 'Documentation', 'Flight missions', 'Interview']::text[], 'https://drive.google.com/file/d/1SwPAK48hAUQKy1NkzkMRvvktUQ4qYXoI/view', '191–193'),
  ('engineering-design', 'Engineering Design', 'Engineering the Future of Energy', 'https://tsaweb.org/competitions/themes-and-problems?hspage=2', 'Participants develop a solution to an annual theme that is based on a specific challenge noted by the National Academy of Engineering (NAE) in its compilation of the grand challenges for engineering in the 21st century. The solution will include a documentation portfolio, a display, and a model/prototype. Semifinalists deliver a presentation and participate in an interview.', 'STEM (General)', 'Team of 2–4', ARRAY['Documentation', 'Display & prototype', 'Presentation', 'Interview']::text[], 'https://drive.google.com/file/d/1SwPAK48hAUQKy1NkzkMRvvktUQ4qYXoI/view', '200–202'),
  ('extemporaneous-speech', 'Extemporaneous Speech', NULL, NULL, 'Participants select a technology-related or TSA topic from among three topic cards and prepare and give a three-to-five-minute speech that communicates their knowledge of the chosen topic. The quality of the speech determines advancement to the semifinalist level of competition, for which an identical competition procedure is followed to determine finalists.', 'Leadership', 'Individual', ARRAY['Onsite speech']::text[], 'https://drive.google.com/file/d/1SwPAK48hAUQKy1NkzkMRvvktUQ4qYXoI/view', '207–208'),
  ('fashion-design-and-technology', 'Fashion Design and Technology', 'Recycled & Repurposed Fashion', 'https://tsaweb.org/competitions/themes-and-problems?hspage=2', 'To address the annual theme, participants demonstrate expertise in fashion design principles by creating a wearable garment, garment patterns, and a documentation portfolio. Semifinalist teams present their garment designs (worn by team models), discuss the design process with evaluators, and respond to interview questions.', 'STEM and the Arts', 'Team of 2–4', ARRAY['Garment', 'Documentation', 'Runway presentation', 'Interview']::text[], 'https://drive.google.com/file/d/1SwPAK48hAUQKy1NkzkMRvvktUQ4qYXoI/view', '214–217'),
  ('flight-endurance', 'Flight Endurance', NULL, NULL, 'Participants design, build, fly, and adjust (trim) a rubber-band powered model aircraft to make long endurance flights inside a contained airspace. Documentation (including elements such as attributes of the model design, drawings, and an analysis of the trim modifications), an inspection of the model and the required model flight box, and official times for two flights are aspects of the evaluation', 'Manufacturing and Transportation Technology', 'Individual', ARRAY['Model aircraft', 'Documentation', 'Timed flights']::text[], 'https://drive.google.com/file/d/1SwPAK48hAUQKy1NkzkMRvvktUQ4qYXoI/view', '225–226'),
  ('forensic-science', 'Forensic Science', NULL, NULL, 'Participants take a test of basic forensic science to qualify for the semifinal round of competition. Semifinalists examine a mock crime scene and demonstrate their knowledge of forensic science through crime scene analysis, with the findings synthesized in a written report/analysis.', 'Technology and Research', 'Team of 2', ARRAY['Test', 'Onsite analysis']::text[], 'https://drive.google.com/file/d/1SwPAK48hAUQKy1NkzkMRvvktUQ4qYXoI/view', '233–234'),
  ('future-technology-and-engineering-teacher', 'Future Technology and Engineering Teacher', NULL, NULL, 'Participants research a developing technology, prepare a video showing an application of the technology in the classroom, and create a lesson plan/activity that features the application and connects to the Standards for Technological and Engineering Literacy (STEL), as well as STEM initiatives and integration. Semifinalists demonstrate the lesson plan and answer questions about their presentation.', 'Leadership', 'Individual', ARRAY['Pre-conference submission', 'Lesson plan', 'Presentation']::text[], 'https://drive.google.com/file/d/1SwPAK48hAUQKy1NkzkMRvvktUQ4qYXoI/view', '241–243'),
  ('hybrid-racer-xl', 'Hybrid Racer XL', 'Tow the Weight', 'https://tsaweb.org/competitions/themes-and-problems?hspage=2', 'Hybrid Racer XL provides a hands-on opportunity for participants to apply science, technology, engineering, and mathematics (STEM) concepts - as well as leadership and 21st century skills such as creativity, teamwork, and problem-solving skills - as they design (according to annual requirements, if any), construct, and race a dual-powered (solar and battery) car.', 'Manufacturing and Transportation Technology', 'Team of 2–4', ARRAY['Build', 'Race']::text[], 'https://drive.google.com/file/d/1SwPAK48hAUQKy1NkzkMRvvktUQ4qYXoI/view', '253–255'),
  ('interior-design', 'Interior Design', 'Tiny Living, Big Impact', 'https://tsaweb.org/competitions/themes-and-problems?hspage=2', 'Applying leadership and 21st century skills, participants develop a color sample and material design board(s) used by interior designers to plan an overall cohesive design based on an annual challenge. Participants must demonstrate an understanding of and aptitude for interior design, developing design boards, and presenting a design interpretation.', 'Architecture and Construction Technology', 'Team of 2 or individual', ARRAY['Design boards', 'Documentation', 'Presentation']::text[], 'https://drive.google.com/file/d/1SwPAK48hAUQKy1NkzkMRvvktUQ4qYXoI/view', '262–265'),
  ('manufacturing-prototype', 'Manufacturing Prototype', 'Display or Container for Collectibles', 'https://tsaweb.org/competitions/themes-and-problems?hspage=2', 'Participants design, fabricate, and use Computer Integrated Manufacturing (CIM) to create a product that addresses the annual theme. A documentation portfolio and the completed product prototype are submitted for evaluation. Semifinalists give a product “sales pitch” and demonstration.', 'Manufacturing and Transportation Technology', 'Team · 1 per chapter', ARRAY['Prototype', 'Documentation', 'Sales pitch']::text[], 'https://drive.google.com/file/d/1SwPAK48hAUQKy1NkzkMRvvktUQ4qYXoI/view', '272–275'),
  ('music-production', 'Music Production', 'Video Game Boss Battle Soundtrack', 'https://tsaweb.org/competitions/themes-and-problems?hspage=2', 'Participants produce an original musical piece that reflects the annual theme on the TSA website under Themes & Problems. The quality of the musical piece and required documentation (including elements such as a plan of work, self-evaluation, and a list of hardware, software, and instruments used) determines advancement to the semifinal level of competition, during which semifinalist participants are interviewed.', 'STEM and the Arts', 'Team or individual', ARRAY['Pre-conference submission', 'Documentation', 'Interview']::text[], 'https://drive.google.com/file/d/1SwPAK48hAUQKy1NkzkMRvvktUQ4qYXoI/view', '282–284'),
  ('on-demand-video', 'On Demand Video', NULL, NULL, 'Once participants receive the challenge details (required criteria, such as props and a line of dialogue) at the national TSA conference, they have 36 hours to produce a 60-second film that showcases video skills, tools, and communication processes. The quality of the completed video production determines the finalists.', 'STEM and the Arts', 'Team · 1 per chapter', ARRAY['Onsite 36-hour film']::text[], 'https://drive.google.com/file/d/1SwPAK48hAUQKy1NkzkMRvvktUQ4qYXoI/view', '289–290'),
  ('photographic-technology', 'Photographic Technology', 'Behind the Scenes', 'https://tsaweb.org/competitions/themes-and-problems?hspage=3', 'Participants produce a photographic portfolio - demonstrating expertise in photo and imaging technology processes - to convey a message based on the annual theme. Semifinalists have 24 hours to complete a portfolio of photos (with required documentation) taken onsite at the national TSA conference. Finalists are determined based on the quality of the semifinal portfolio, the portfolio presentation, and interview responses.', 'STEM and the Arts', 'Individual', ARRAY['Pre-conference submission', 'Onsite portfolio', 'Interview']::text[], 'https://drive.google.com/file/d/1SwPAK48hAUQKy1NkzkMRvvktUQ4qYXoI/view', '297–299'),
  ('prepared-presentation', 'Prepared Presentation', 'From Science Fiction to Reality', 'https://tsaweb.org/competitions/themes-and-problems?hspage=3', 'Participants deliver a three-to-five-minute oral presentation related to the current national TSA conference theme. Both semifinalists and finalists are determined based on the quality of the presentation and the appropriate use and content of the accompanying required slide deck.', 'Leadership', 'Individual', ARRAY['Presentation']::text[], 'https://drive.google.com/file/d/1SwPAK48hAUQKy1NkzkMRvvktUQ4qYXoI/view', '306–309'),
  ('promotional-design', 'Promotional Design', 'Milestone Diner', 'https://tsaweb.org/competitions/themes-and-problems?hspage=3', 'Participants use computerized graphic communications layout and design skills to produce a promotional resource packet. The resource must address the annual theme/problem and include at least four printed publication items and required documentation. Semifinalists demonstrate publishing competency in an onsite technical design challenge.', 'Communications Technology', 'Individual', ARRAY['Pre-conference submission', 'Onsite challenge']::text[], 'https://drive.google.com/file/d/1SwPAK48hAUQKy1NkzkMRvvktUQ4qYXoI/view', '314–316'),
  ('robotics', 'Robotics', 'Obstacle Course Scoring Challenge', 'https://tsaweb.org/docs/default-source/competitions/themes-and-problems-2026-2027/high-school/2027-hs-robotics.pdf?sfvrsn=6c629180_3', 'Participants design, build, document, and test a robot assembled using open-sourced parts according to stated specifications and to meet the challenge of the yearly theme/problem.', 'Manufacturing and Transportation Technology', 'Team of 2–6', ARRAY['Robot', 'Documentation', 'Onsite challenge', 'Interview']::text[], 'https://drive.google.com/file/d/1SwPAK48hAUQKy1NkzkMRvvktUQ4qYXoI/view', '321–322'),
  ('software-development', 'Software Development', 'Software for Learning & Skills', 'https://tsaweb.org/competitions/themes-and-problems?hspage=3', 'Participants use their knowledge of cutting-edge technologies, algorithm design, problem-solving principles, effective communication, and collaboration to design, implement, test, document, and present a software development project of educational or social value. Both semifinalists and finalists are determined based on the quality of the presentation and project.', 'Computer Science', 'Team · 1 per chapter', ARRAY['Pre-conference submission', 'Presentation', 'Interview']::text[], 'https://drive.google.com/file/d/1SwPAK48hAUQKy1NkzkMRvvktUQ4qYXoI/view', '327–328'),
  ('stem-mass-media', 'STEM Mass Media', 'Right-Handedness & Human Evolution', 'https://tsaweb.org/competitions/themes-and-problems?hspage=3', 'In response to an annual theme, participants use written and verbal communication skills to convey a news story in both a video broadcast (preliminary round) and a digital written format (semifinal round). Participants must demonstrate a strong understanding of journalism etiquette and the common practices of the field of mass media.', 'Communications Technology', 'Team of 2–3', ARRAY['Pre-conference submission', 'Onsite writing']::text[], 'https://drive.google.com/file/d/1SwPAK48hAUQKy1NkzkMRvvktUQ4qYXoI/view', '334–336'),
  ('structural-design-and-engineering', 'Structural Design and Engineering', 'Balsa Load-Bearing Structure', 'https://tsaweb.org/docs/default-source/competitions/themes-and-problems-2026-2027/high-school/2027-structural-design-and-engineering-problem-statement.pdf?sfvrsn=56397e65_1', 'Participants apply the principles of structural engineering to design and construct a structure that complies with the annual challenge. An assessment of the required documentation and the destructive testing of the structure (to determine its design efficiency) determine both semifinalists and finalists.', 'Architecture and Construction Technology', 'Team of 2', ARRAY['Structure', 'Documentation', 'Load testing']::text[], 'https://drive.google.com/file/d/1SwPAK48hAUQKy1NkzkMRvvktUQ4qYXoI/view', '343–346'),
  ('technology-bowl', 'Technology Bowl', NULL, NULL, 'Participants demonstrate their knowledge of TSA and concepts addressed in technology content standards by completing an objective test. Semifinalist teams participate in a question/response, head-to-head, team competition.', 'Leadership', 'Team of 3', ARRAY['Test', 'Head-to-head']::text[], 'https://drive.google.com/file/d/1SwPAK48hAUQKy1NkzkMRvvktUQ4qYXoI/view', '354–356'),
  ('technology-problem-solving', 'Technology Problem Solving', NULL, NULL, 'Participants use problem-solving skills to design and construct a finite solution to a challenge provided onsite at the conference. Solutions are evaluated at the end of 90 minutes using measures appropriate to the challenge, such as elapsed time, horizontal or vertical distance, and/or strength.', 'STEM (General)', 'Team of 2', ARRAY['Onsite challenge']::text[], 'https://drive.google.com/file/d/1SwPAK48hAUQKy1NkzkMRvvktUQ4qYXoI/view', '362'),
  ('transportation-modeling', 'Transportation Modeling', 'Cartoon & Comic Vehicles', 'https://tsaweb.org/competitions/themes-and-problems?hspage=3', 'Participants research, design, and produce a scale model of a vehicle that complies with the annual design problem. A display for the model and a documentation portfolio – containing elements such as a description of the vehicle, photographs and commentary detailing the vehicle production, and technical illustrations – are required. Semifinalists participate in an interview.', 'Manufacturing and Transportation Technology', 'Individual', ARRAY['Scale model', 'Documentation', 'Interview']::text[], 'https://drive.google.com/file/d/1SwPAK48hAUQKy1NkzkMRvvktUQ4qYXoI/view', '368–370'),
  ('video-game-design', 'Video Game Design', 'Deep-Space Puzzle RPG', 'https://tsaweb.org/competitions/themes-and-problems?hspage=4', 'Participants design, build, and launch an E-rated online video game – with accompanying required documentation - that addresses the annual theme. Semifinalists participate in an interview to demonstrate the knowledge and expertise they gained during the development of the game.', 'Computer Science', 'Team of 2 or more', ARRAY['Pre-conference submission', 'Documentation', 'Interview']::text[], 'https://drive.google.com/file/d/1SwPAK48hAUQKy1NkzkMRvvktUQ4qYXoI/view', '376–379'),
  ('virtual-reality-simulation', 'Virtual Reality Simulation (VR)', 'High-Speed First Aid Simulation', 'https://tsaweb.org/competitions/themes-and-problems?hspage=4', 'Participants use video and 3D computer graphics tools and design processes to create a two-to-three-minute VR visualization (accompanied by supporting documentation) that addresses the annual theme. Semifinalists deliver a presentation about their visualization and participate in an interview.', 'Computer Science', 'Team or individual', ARRAY['VR visualization', 'Documentation', 'Presentation', 'Interview']::text[], 'https://drive.google.com/file/d/1SwPAK48hAUQKy1NkzkMRvvktUQ4qYXoI/view', '384–386'),
  ('vlogging', 'Vlogging', 'The Butterfly Effect', 'https://tsaweb.org/competitions/themes-and-problems?hspage=4', 'Vlogging encourages good storytelling, videography, and editing techniques to create a coherent series of creative work. Applying leadership and 21st century skills, participants use digital video technology to create original content that reflects an annual technology theme. Semifinalists complete an onsite challenge to produce additional video(s). Required criteria, such as props, lines of dialog, topics, etc., will be revealed at the semifinalist orientation meeting.', 'STEM and the Arts', 'Team of 2–6', ARRAY['Pre-conference submission', 'Onsite challenge']::text[], 'https://drive.google.com/file/d/1SwPAK48hAUQKy1NkzkMRvvktUQ4qYXoI/view', '392–394'),
  ('webmaster', 'Webmaster', 'AI Learning Portal', 'https://tsaweb.org/competitions/themes-and-problems?hspage=4', 'Participants design, build, and launch a website that addresses the annual challenge. Semifinalists participate in an interview to demonstrate the knowledge and expertise gained during the development of the website.', 'Computer Science', 'Team of up to 6 or individual', ARRAY['Pre-conference submission', 'Interview']::text[], 'https://drive.google.com/file/d/1SwPAK48hAUQKy1NkzkMRvvktUQ4qYXoI/view', '399–401')
